import json
import re

ai = node_outputs.get('ai_blog', {})
status = ai.get('status', None)
raw = ai.get('data', '')
blog_content = ''
blog_title = 'Untitled Blog Post'
blog_excerpt = ''
image_prompts = []
category_ids = []
tag_ids = []

# Extract the actual text content from the AI response
full_text = ''
if isinstance(raw, str):
    full_text = raw
elif isinstance(raw, dict):
    choices = raw.get('choices')
    if isinstance(choices, list) and len(choices) > 0:
        parts = []
        for c in choices:
            if isinstance(c, dict):
                msg = c.get('message') or c.get('delta') or {}
                if isinstance(msg, dict):
                    part = msg.get('content') or msg.get('text') or ''
                else:
                    part = c.get('text', '')
                if not part:
                    part = c.get('text', '')
                if part:
                    parts.append(part)
        if parts:
            full_text = "\n".join(parts)
        else:
            full_text = raw.get('text', json.dumps(raw, ensure_ascii=False))
    else:
        if 'message' in raw and isinstance(raw.get('message'), dict):
            full_text = raw.get('message', {}).get('content', '')
        elif 'text' in raw:
            full_text = raw.get('text', '')
        else:
            full_text = json.dumps(raw, ensure_ascii=False)
elif isinstance(raw, list):
    items = []
    for it in raw:
        items.append(it if isinstance(it, str) else json.dumps(it, ensure_ascii=False))
    full_text = "\n".join(items)
else:
    full_text = str(raw)

# Extract title
title_match = re.search(r'<title>(.*?)</title>', full_text, re.IGNORECASE | re.DOTALL)
if title_match:
    blog_title = title_match.group(1).strip()
    full_text = re.sub(r'<title>.*?</title>', '', full_text, flags=re.IGNORECASE | re.DOTALL)

# Extract category IDs
category_ids_match = re.search(r'<category_ids>(.*?)</category_ids>', full_text, re.IGNORECASE | re.DOTALL)
if category_ids_match:
    category_ids_str = category_ids_match.group(1).strip()
    # Convert to list of integers
    try:
        if category_ids_str:  # Only process if not empty
            category_ids = [int(id.strip()) for id in category_ids_str.split(',') if id.strip()]
        else:
            category_ids = [1]  # Default to uncategorized if empty
    except:
        category_ids = [1]  # Default to uncategorized on error
    full_text = re.sub(r'<category_ids>.*?</category_ids>', '', full_text, flags=re.IGNORECASE | re.DOTALL)
else:
    category_ids = [1]  # Default to uncategorized

# Extract tag IDs
tag_ids_match = re.search(r'<tag_ids>(.*?)</tag_ids>', full_text, re.IGNORECASE | re.DOTALL)
if tag_ids_match:
    tag_ids_str = tag_ids_match.group(1).strip()
    # Convert to list of integers
    try:
        if tag_ids_str:  # Only process if not empty
            tag_ids = [int(id.strip()) for id in tag_ids_str.split(',') if id.strip()]
        else:
            tag_ids = []  # Empty list if no tags
    except:
        tag_ids = []  # Empty list on error
    full_text = re.sub(r'<tag_ids>.*?</tag_ids>', '', full_text, flags=re.IGNORECASE | re.DOTALL)
else:
    tag_ids = []  # Empty list if no tag_ids tag found

# Extract image prompts and their captions
image_prompt_matches = re.findall(r'<image-prompt>(.*?)</image-prompt>', full_text, re.IGNORECASE | re.DOTALL)
for prompt in image_prompt_matches:
    image_prompts.append(prompt.strip())

# Remove image prompts from content
full_text = re.sub(r'<image-prompt>.*?</image-prompt>', '', full_text, flags=re.IGNORECASE | re.DOTALL)

# Also extract captions from placeholders if they exist
image_captions = []
placeholder_matches = re.findall(r'<figure[^>]*data-image-index="(\d+)"[^>]*>.*?<figcaption>(.*?)</figcaption>', full_text, re.IGNORECASE | re.DOTALL)
for idx, caption in placeholder_matches:
    image_captions.append(caption.strip())

blog_content = full_text.strip()

# Create excerpt
excerpt_match = re.search(r'<p[^>]*>(.*?)</p>', blog_content, re.IGNORECASE | re.DOTALL)
if excerpt_match:
    blog_excerpt = re.sub(r'<[^>]+>', '', excerpt_match.group(1))[:200].strip()
else:
    clean_text = re.sub(r'<[^>]+>', '', blog_content)
    blog_excerpt = clean_text[:200].strip()

if blog_excerpt and not blog_excerpt.endswith('.'):
    blog_excerpt += '...'

output = {}
output['status'] = status
output['success'] = ai.get('success', True if status == 200 else False)
output['blog_content'] = blog_content
output['blog_title'] = blog_title
output['blog_excerpt'] = blog_excerpt
output['image_prompts'] = image_prompts
output['image_captions'] = image_captions
output['category_ids'] = category_ids
output['tag_ids'] = tag_ids
output['raw'] = raw
